<?php
require 'config.php';require 'auth.php';require 'helpers.php';$facilities=$conn->query('SELECT f.*,COUNT(c.id) court_count FROM facilities f LEFT JOIN courts c ON c.facility_id=f.id AND c.is_active=1 WHERE f.is_active=1 GROUP BY f.id ORDER BY f.facility_name')->fetch_all(MYSQLI_ASSOC);$pageTitle='Facilities';require 'partials/header.php';?>
<div class="page-header"><h1>Sports Facilities</h1><p>Browse all active campus courts and activity areas.</p></div><div class="card-grid"><?php foreach($facilities as $f): ?><article class="card"><img class="card-thumb" src="<?= htmlspecialchars(entity_image_url($f)) ?>" alt="<?= htmlspecialchars($f['facility_name']) ?>"><h3><?= htmlspecialchars($f['facility_name']) ?></h3><p><?= htmlspecialchars($f['location']) ?></p><p><?= htmlspecialchars($f['description']) ?></p><p>RM<?= number_format($f['price_per_hour'],2) ?>/hour &middot; <?= (int)$f['court_count'] ?> area(s)</p><a class="btn" href="schedule.php?facility_id=<?= (int)$f['id'] ?>">View Schedule</a></article><?php endforeach; ?></div><?php require 'partials/footer.php'; ?>

